// Helper to sanitize title comparison
function normalizeText(text) {
  return text
    .replace(/\s+/g, '')
    .replace(/[أإآ]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/ى/g, 'ي')
    .toLowerCase();
}

async function runMigration() {
  console.log("Starting catalog database migration...");

  // 1. Fetch existing categories and services
  const { data: currentCategories, error: catFetchErr } = await supabase.from('categories').select('*');
  if (catFetchErr) {
    console.error("Error loading categories:", catFetchErr);
    return;
  }
  const { data: currentServices, error: servFetchErr } = await supabase.from('services').select('*');
  if (servFetchErr) {
    console.error("Error loading services:", servFetchErr);
    return;
  }

  // 2. Map existing services' category_ids to the new ones safely
  console.log("Remapping categories for existing services...");
  for (const serv of currentServices) {
    const newCatId = categoryMapping[serv.category_id];
    if (newCatId && newCatId !== serv.category_id) {
      console.log(`Re-assigning service ${serv.id} from category ${serv.category_id} to ${newCatId}`);
      await supabase.from('services').update({ category_id: newCatId }).eq('id', serv.id);
    }
  }

  // 3. Delete old categories from the database if they are no longer in our 16
  console.log("Removing outdated categories...");
  const validCatIds = categoriesToSeed.map(c => c.id);
  for (const cat of currentCategories) {
    if (!validCatIds.includes(cat.id)) {
      console.log(`Deleting obsolete category: ${cat.id}`);
      await supabase.from('categories').delete().eq('id', cat.id);
    }
  }

  // 4. Upsert the 16 new categories
  console.log("Upserting 16 categories...");
  for (const cat of categoriesToSeed) {
    const { error } = await supabase.from('categories').upsert(cat);
    if (error) {
      console.error(`Failed to upsert category ${cat.id}:`, error);
    } else {
      console.log(`Category verified/created: ${cat.id}`);
    }
  }

  // Reload current services list for deduplication checks
  const { data: updatedServices } = await supabase.from('services').select('*');
  const existingServiceNamesNormalized = new Map(
    updatedServices.map(s => [normalizeText(s.title_ar), s])
  );

  let skippedCount = 0;
  let addedCount = 0;

  // 5. Seed new services with deduplication logic
  console.log("Upserting service items with duplicate prevention...");
  for (const s of servicesToSeed) {
    const normalizedTitleAr = normalizeText(s.title_ar);
    
    // Check if the service title or ID already exists in the catalog
    const exactMatch = updatedServices.find(item => item.id === s.id);
    const semanticMatch = existingServiceNamesNormalized.get(normalizedTitleAr);

    if (exactMatch || semanticMatch) {
      const match = exactMatch || semanticMatch;
      console.log(`Skipping duplicate service: "${s.title_ar}" (already exists as ID: ${match.id})`);
      skippedCount++;
      continue;
    }

    // Insert new service item safely
    const { error } = await supabase.from('services').insert({
      id: s.id,
      title_ar: s.title_ar,
      title_en: s.title_en,
      desc_ar: s.desc_ar,
      desc_en: s.desc_en,
      category_id: s.category_id,
      price: "حسب الاتفاق",
      docs_ar: s.docs_ar,
      docs_en: s.docs_en,
      completion_time_ar: s.completion,
      completion_time_en: s.completion,
      keywords: [s.title_ar, s.title_en, s.id],
      visible: true,
      order: 10
    });

    if (error) {
      console.error(`Failed to insert service ${s.id}:`, error);
    } else {
      console.log(`New service added: "${s.title_ar}"`);
      addedCount++;
    }
  }

  console.log(`Migration complete! Added ${addedCount} services, skipped ${skippedCount} duplicates.`);
}

runMigration();
